import { Component, Vue, Prop, Emit } from 'vue-property-decorator';
import { ISettingsOption } from '../../../types';

@Component({
    name: 'InputColourPicker'
})
export default class ColourPicker extends Vue {
    @Prop({
        required: true,
        type: String
    })
    public selected: string;

    @Prop({
        required: true,
        type: Array<string>
    })
    public colours: Array<ISettingsOption>;

    @Emit('onChange')
    public onChange(colour: string) {
        return colour;
    }
}